begin;
create temporary table af(actor uuid,other_actor uuid,wid uuid,sid uuid,other_site uuid,id uuid,command jsonb);
insert into af values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),null);
update af set command=jsonb_build_object('action','meeting','id',id,'agenda','Discuss the new tool page using approved facts.','mode','announcement','participants',jsonb_build_array('coordinator','content','quality'),'reviewed',true,'inputMode','corrected-transcript');
insert into auth.users(id) select actor from af union all select other_actor from af;
insert into public.bizoveya_workspaces(id,owner_id,name) select wid,actor,'Agency fixture' from af;
insert into public.bizoveya_memberships(workspace_id,user_id,role) select wid,actor,'owner' from af union all select wid,other_actor,'viewer' from af;
insert into public.bizoveya_sites(id,workspace_id,name,mode,kind,status,created_by) select sid,wid,'Agency A','native_business','business','active',actor from af union all select other_site,wid,'Agency B','native_business','business','active',actor from af;
create function pg_temp.expect_agency(q text,n text) returns void language plpgsql as $$begin begin execute q;exception when others then if strpos(sqlerrm,n)>0 then return;end if;raise;end;raise exception 'Expected %',n;end;$$;
do $$begin execute format('grant usage on schema %I to authenticated',(select nspname from pg_namespace where oid=pg_my_temp_schema()));end;$$;grant all on af to authenticated;
set local role authenticated;select set_config('request.jwt.claim.sub',(select actor::text from af),true);
select public.bz_agency_command(wid,sid,command) from af;
select public.bz_agency_command(wid,sid,command) from af;
do $$declare r jsonb;begin select public.bz_agency_inventory(wid,sid) into r from af;if jsonb_array_length(r)<>1 or r#>>'{0,version}'<>'1' or r#>>'{0,snapshot,runtimeEnabled}'<>'false' or jsonb_array_length(r#>'{0,events}')<>1 then raise exception 'Creation retry or snapshot boundary failed';end if;end;$$;
select pg_temp.expect_agency(format('select public.bz_agency_command(%L,%L,%L::jsonb)',wid,sid,jsonb_set(command,'{reviewed}','false')),'bz_invalid_agency_command') from af;
select pg_temp.expect_agency(format('select public.bz_agency_command(%L,%L,%L::jsonb)',wid,other_site,jsonb_build_object('action','cancel','id',id,'expectedVersion',1,'reason','Cancel','reviewed',true)),'bz_agency_unavailable') from af;
select public.bz_agency_command(wid,sid,jsonb_build_object('action','accept-decision','id',id,'expectedVersion',1,'reason','Use private drafts only.','reviewed',true)) from af;
select pg_temp.expect_agency(format('select public.bz_agency_command(%L,%L,%L::jsonb)',wid,sid,jsonb_build_object('action','cancel','id',id,'expectedVersion',1,'reason','Stale','reviewed',true)),'bz_conflict') from af;
select public.bz_agency_command(wid,sid,jsonb_build_object('action','cancel','id',id,'expectedVersion',2,'reason','Replaced agenda.','reviewed',true)) from af;
select pg_temp.expect_agency(format('select public.bz_agency_command(%L,%L,%L::jsonb)',wid,sid,jsonb_build_object('action','defer','id',id,'expectedVersion',3,'reason','Cannot revive cancelled proposal.','reviewed',true)),'bz_conflict') from af;
select set_config('request.jwt.claim.sub',(select other_actor::text from af),true);
select public.bz_agency_inventory(wid,sid) from af;
select pg_temp.expect_agency(format('select public.bz_agency_command(%L,%L,%L::jsonb)',wid,sid,command),'bz_forbidden') from af;
select pg_temp.expect_agency('select * from bizoveya_private.agency_records','permission denied');
reset role;
do $$begin if (select count(*) from bizoveya_private.agency_events)<>3 then raise exception 'Unexpected agency events';end if;end;$$;
delete from public.bizoveya_sites where id=(select sid from af);
do $$begin if exists(select 1 from bizoveya_private.agency_records where id=(select id from af)) then raise exception 'Agency cascade failed';end if;end;$$;
rollback;
